  size="40"
  stroke="4"
  strokeLength="0.15"
  bgOpacity="0.3"
  speed="1.4"
  color="#8b5cf6" 
/>
        </div>}
        <div className='flex flex-col items-center justify-center w-[90%] gap-1 py-10'> 
