      </div>
      <div className="w-[90%] h-screen flex flex-col items-center justify-end mb-18 gap-5">
        <div
          onClick={() => {
            navigate("/update-preferences");
          }}
          className="w-full"
        >
          <Button text="Next" />
        </div>
      </div>
    </div>
  );
};

export default UpdatePicture;

