import axios from "axios";
import { Trefoil } from "ldrs/react";
import "ldrs/react/Trefoil.css";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useSearchParams } from "react-router-dom";

const UserProfilePage = () => {
  const [openSection, setOpenSection] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const [refresh, setRefresh] = useState(true);

  const [user, setUser] = useState(null);

  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  const [sections, setSections] = useState([]);

  const handleToggle = (key) => {
    setOpenSection(openSection === key ? null : key);
  };

  const newConnection = async () => {
    setLoading(true);
    try {
      const response = await axios.post(
        `${import.meta.env.VITE_BASE_URL}/user/new-connection`,
        { userId: searchParams.get("userid") },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
    } catch (error) {
      console.log(error);
      setError("Unknown Error occured. Please try again later.");
    } finally {
      setLoading(false);
      setRefresh(!refresh);
    }
  };

  const acceptConnection = async () => {
    setLoading(true);
    try {
      const response = await axios.post(
        `${import.meta.env.VITE_BASE_URL}/user/accept-connection`,
        { userId: searchParams.get("userid") },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
    } catch (error) {
      console.log(error);
      setError("Unknown Error occured. Please try again later.");
    } finally {
      setLoading(false);
      setRefresh(!refresh);
    }
  };

  const rejectConnection = async () => {
    setLoading(true);
    try {
      const response = await axios.post(
        `${import.meta.env.VITE_BASE_URL}/user/reject-connection`,
        { userId: searchParams.get("userid") },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
    } catch (error) {
      console.log(error);
      setError("Unknown Error occured. Please try again later.");
    } finally {
      setLoading(false);
      setRefresh(!refresh);
    }
  };

  const disconnect = async () => {
    setLoading(true);
    try {
      const response = await axios.post(
        `${import.meta.env.VITE_BASE_URL}/user/disconnect-connection`,
        { userId: searchParams.get("userid") },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
    } catch (error) {
      console.log(error);
      setError("Unknown Error occured. Please try again later.");
    } finally {
      setLoading(false);
      setRefresh(!refresh);
    }
  };

  useEffect(() => {
    setLoading(true);
    const fetchData = async () => {
      try {
        const response = await axios.post(
          `${
            import.meta.env.VITE_BASE_URL
          }/user/fetch-user-details-for-profile`,
          { userId: searchParams.get("userid") },
          {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          }
        );

        if (response.status === 200) {
          const formatDate = (dateStr) => {
            if (!dateStr) return "";
            const date = new Date(dateStr);
            if (isNaN(date)) return dateStr;
            const day = String(date.getDate()).padStart(2, "0");
            const month = String(date.getMonth() + 1).padStart(2, "0");
            const year = date.getFullYear();
            return `${day}-${month}-${year}`;
          };

          const userData = [
            {
              key: "about",
              icon: "https://res.cloudinary.com/dbzcsfi3e/image/upload/v1749043298/Vector_6_drfg5u.png",
              label: "About me",
              content: (
                <div className="px-7 py-3 overflow-scroll text-white text-sm scrollbar-hidden">
